function validate([price, tastiness, maxAmount, maxCoupons]) {
  if (price.length !== tastiness.length) return 'price and tastiness must have the same length.';
  if (price.length < 1 || price.length > 100) return 'There are 1 to 100 fruits.';
  if ([...price, ...tastiness].some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each price and tastiness is between 0 and 1000.';
  if (!Number.isInteger(maxAmount) || maxAmount < 0 || maxAmount > 1000) return 'maxAmount is between 0 and 1000.';
  if (!Number.isInteger(maxCoupons) || maxCoupons < 0 || maxCoupons > 5) return 'maxCoupons is between 0 and 5.';
  return null;
}

