function maxTastiness(price, tastiness, maxAmount, maxCoupons) {
  const dp = Array.from({ length: maxAmount + 1 }, () => new Array(maxCoupons + 1).fill(0));
  for (let i = 0; i < price.length; i++) {
    const full = price[i];
    const half = Math.floor(price[i] / 2);
    for (let amount = maxAmount; amount >= half; amount--) {
      for (let coupons = maxCoupons; coupons >= 0; coupons--) {
        if (amount >= full) {
          dp[amount][coupons] = Math.max(dp[amount][coupons], dp[amount - full][coupons] + tastiness[i]);
        }
        if (coupons > 0) {
          dp[amount][coupons] = Math.max(dp[amount][coupons], dp[amount - half][coupons - 1] + tastiness[i]);
        }
      }
    }
  }
  return dp[maxAmount][maxCoupons];
}

