function maxTastiness(price, tastiness, maxAmount, maxCoupons) {
  const explore = (i, money, coupons) => {
    if (i === price.length) return 0;
    let best = explore(i + 1, money, coupons);
    if (price[i] <= money) best = Math.max(best, tastiness[i] + explore(i + 1, money - price[i], coupons));
    const cut = Math.floor(price[i] / 2);
    if (coupons > 0 && cut <= money) best = Math.max(best, tastiness[i] + explore(i + 1, money - cut, coupons - 1));
    return best;
  };
  return explore(0, maxAmount, maxCoupons);
}

