function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = 100;
    const price = Array.from({ length: n }, () => int(0, 1000));
    const tastiness = Array.from({ length: n }, () => int(0, 1000));
    return [price, tastiness, int(400, 1000), int(0, 5)];
  }
  const n = int(1, 7);
  const priceCap = rand() < 0.2 ? 1000 : 30;
  const price = Array.from({ length: n }, () => int(0, priceCap));
  const tastiness = Array.from({ length: n }, () => int(0, 20));
  const maxAmount = rand() < 0.15 ? 0 : int(0, priceCap === 1000 ? 1000 : 60);
  return [price, tastiness, maxAmount, int(0, 3)];
}
